-- ========================================
-- TABLE: public.document_processing_tasks
-- ========================================

CREATE TABLE public.document_processing_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid NOT NULL,
    task_type character varying(50) NOT NULL,
    status character varying(50) NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    error_message text,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    batch_id uuid,
    CONSTRAINT document_processing_tasks_document_id_fkey FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
    CONSTRAINT fk_document_processing_tasks_batch FOREIGN KEY (batch_id) REFERENCES document_chunk_batches(id) ON DELETE CASCADE,
    CONSTRAINT document_processing_tasks_pkey PRIMARY KEY (id)
);

CREATE INDEX idx_document_tasks_document_id ON public.document_processing_tasks USING btree (document_id);
CREATE INDEX idx_document_tasks_status ON public.document_processing_tasks USING btree (status);
CREATE INDEX idx_document_tasks_type ON public.document_processing_tasks USING btree (task_type);
CREATE INDEX idx_document_tasks_status_created ON public.document_processing_tasks USING btree (status, created_at);
CREATE INDEX idx_document_processing_tasks_batch_id ON public.document_processing_tasks USING btree (batch_id);
CREATE INDEX idx_document_processing_tasks_type_status ON public.document_processing_tasks USING btree (task_type, status);
